#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n' "$DIM"
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }
fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1" "$RESET"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but the input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r -s input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# an existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$ENV_FILE"
  mv "$tmp" "$ENV_FILE" 2>/dev/null || true
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return 0
    fi
  fi
  SKIPPED+=("GitHub secret $name")
  warn "couldn't set GitHub secret $name (gh missing or unauthenticated); set it manually later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ All stages done%s\n\n' "$BOLD" "$GREEN" "$RESET"
  if (( ${#WRITTEN_ENV[@]} )); then
    note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE:"
    for k in "${WRITTEN_ENV[@]}"; do note "  - $k"; done
  fi
  if (( ${#WRITTEN_SECRET[@]} )); then
    note "set ${#WRITTEN_SECRET[@]} GitHub secret(s):"
    for k in "${WRITTEN_SECRET[@]}"; do note "  - $k"; done
  fi
  if (( ${#SKIPPED[@]} )); then
    printf '\n%s  %s skipped thing(s):%s\n' "$DIM" "${#SKIPPED[@]}" "$RESET"
    for k in "${SKIPPED[@]}"; do note "  - $k"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human must take.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"
FIXTURES_DIR="device-check/fixtures"
RESULTS_DIR="device-check/results"
CERT_DIR=".prototype-cert"
SERVER_LOG="$CERT_DIR/server.log"
SERVER_PID="$CERT_DIR/server.pid"
SERVER_PORT="${PORT:-8443}"
SERVER_STARTED_BY_US=0
SERVER_URL=""

# ── Stage 1: prepare fixtures ────────────────────────────────────────────────
stage "Prepare bundled fixtures"
say "Extracts the 3 bundled fixtures from the research branch into device-check/fixtures/."
say "These are fetched by the phone from the same HTTPS server."
say ""
if [[ ! -f "$REPO_ROOT/research/fixture-corpus/corpus/manifest.json" ]] \
   && ! git show research/fixture-corpus:research/fixture-corpus/corpus/manifest.json >/dev/null 2>&1; then
  fail "research/fixture-corpus branch is missing (git fetch it first)."
  exit 1
fi
mkdir -p "$FIXTURES_DIR"
for spec in \
  "heic-tiff/photo-12mp.heic|6209077|59ac73d3ca385b7a2e7d2c6b7b7d35222bf83132b569145951053fba2b8ad0ac" \
  "large/photo-12mp-qr-corner.jpg|2253600|cad3f2a29563c3ae8cd8d58f3c89b47d3aa649530d88b0dd73d183f687f9a326" \
  "large/photo-48mp-qr-corner.jpg|7387155|bfdee585adaffd22a70d2b2bc2193ae54a9a2aafa075391b61a68dc01927b70f"; do
  IFS='|' read -r rel size sha256 <<< "$spec"
  dest="$FIXTURES_DIR/$(basename "$rel")"
  step "extracting $rel"
  if [[ -f "$dest" ]] && [[ "$(stat -c%s "$dest")" == "$size" ]] \
     && echo "$sha256  $dest" | sha256sum -c --quiet 2>/dev/null; then
    note "  already present and verified, skipping"
    continue
  fi
  git show "research/fixture-corpus:research/fixture-corpus/corpus/$rel" > "$dest"
  if [[ "$(stat -c%s "$dest")" != "$size" ]]; then
    warn "  size mismatch (got $(stat -c%s "$dest") bytes, expected $size)"
  fi
  if ! echo "$sha256  $dest" | sha256sum -c --quiet 2>/dev/null; then
    warn "  sha256 mismatch — re-fetch from the research branch if the phone can't decode it"
  fi
done
say ""
say "✓ fixtures in $FIXTURES_DIR/"
pause "Ready to start the server?"

# ── Stage 2: start HTTPS server ─────────────────────────────────────────────
stage "Start HTTPS server"
if (echo >/dev/tcp/127.0.0.1/"$SERVER_PORT") 2>/dev/null; then
  if confirm "Port $SERVER_PORT is already in use — reuse the running server?"; then
    note "  reusing whatever is already on $SERVER_PORT (make sure it's dev-https.mjs)"
    SERVER_URL="https://$(hostname -I 2>/dev/null | awk '{print $1}'):${SERVER_PORT}"
  else
    fail "port $SERVER_PORT is taken; export PORT=<other> and re-run"
    exit 1
  fi
else
  step "starting node scripts/dev-https.mjs (self-signed cert, LAN-only)"
  mkdir -p "$CERT_DIR"
  PORT="$SERVER_PORT" nohup node scripts/dev-https.mjs > "$SERVER_LOG" 2>&1 &
  SERVER_PID_VAL=$!
  echo "$SERVER_PID_VAL" > "$SERVER_PID"
  SERVER_STARTED_BY_US=1
  for _ in $(seq 1 20); do
    (echo >/dev/tcp/127.0.0.1/"$SERVER_PORT") 2>/dev/null && break
    sleep 0.3
  done
  if (echo >/dev/tcp/127.0.0.1/"$SERVER_PORT") 2>/dev/null; then
    SERVER_URL=$(grep -o 'https://[0-9.]*:[0-9]*' "$SERVER_LOG" | head -n1)
    say ""
    say "✓ server is up: $SERVER_URL"
    say "  device-check page: $SERVER_URL/device-check/"
    say "  camera prototype:  $SERVER_URL/index.html?camera=a"
    say "  server log:        tail -f $SERVER_LOG"
  else
    fail "server did not come up; see $SERVER_LOG"
    exit 1
  fi
fi
pause "Ready for the iPhone?"

# ── Stage 3: iPhone Safari — browser tests ──────────────────────────────────
stage "iPhone Safari — browser tests"
say "On the iPhone, open the device-check page in Safari and run every test:"
say ""
step "open on the phone:  $SERVER_URL/device-check/"
step "accept the self-signed certificate warning once (Details → visit this website)"
step "run 'Bundled HEIC decode', '12 MP JPEG', then '48 MP photo' (last one may be slow)"
step "run the two 'File picker' inputs — pick the SAME HEIC photo from Photos both times"
step "run 'Special HEIC variants' — pick grid / HDR / multi-image HEICs and label each one"
step "run 'Camera capture path' — take one photo, then set the iOS Camera format setting"
step "run 'Canvas area limit probe' — the largest probe may crash the tab; results persist"
step "tap 'Send results to computer' with the label it suggests (default iphone-safari)"
ask DEVICE_LABEL "Phone label (default iphone-safari):"
pause "Tap Send results on the phone, then come back and press Enter."
RESULTS_FILE="$RESULTS_DIR/${DEVICE_LABEL:-iphone-safari}.json"
if [[ -f "$RESULTS_FILE" ]]; then
  say "✓ received $RESULTS_FILE"
else
  warn "no results file at $RESULTS_FILE — the phone's send failed?"
  warn "check the server log: tail -5 $SERVER_LOG"
  pause "Press Enter to continue anyway (or Ctrl-C to fix the send first)."
fi
RESULTS_FILE="$RESULTS_DIR/${DEVICE_LABEL:-iphone-safari}.json"

# ── Stage 4: iPhone — camera prototype notes ────────────────────────────────
stage "iPhone — camera prototype (variant A)"
say "Now the camera prototype, on the same phone:"
say ""
step "open on the phone:  $SERVER_URL/index.html?camera=a"
step "allow the camera permission, then scan continuously for ~5 minutes"
step "notice: decode speed, whether the phone heats up, torch/zoom controls"
step "when done, go back to the device-check page and fill the 'Camera prototype notes' section"
step "tap 'Send results to computer' again (same label: ${DEVICE_LABEL:-iphone-safari})"
pause "Tap Send results on the phone, then come back and press Enter."
if [[ -f "$RESULTS_FILE" ]]; then
  say "✓ still received at $RESULTS_FILE (re-sent with camera notes)"
else
  warn "results file disappeared — re-send from the phone"
fi

# ── Stage 5: iPhone — Home Screen web app ───────────────────────────────────
stage "iPhone — Home Screen web app re-prompt"
say "The Home Screen web-app permission re-prompt (WebKit bugs 327237 / 215884):"
say ""
step "on the iPhone, open the camera prototype again in Safari"
step "tap Share → 'Add to Home Screen'"
step "close Safari, then open the camera prototype from the Home Screen icon"
step "note whether it re-prompts for camera permission (it should, that's the bug)"
step "go back to the device-check page in Safari and set the 'Home Screen web app re-prompt' select"
step "tap 'Send results to computer' again (same label: ${DEVICE_LABEL:-iphone-safari})"
pause "Tap Send results on the phone, then come back and press Enter."
if [[ -f "$RESULTS_FILE" ]]; then
  say "✓ still received at $RESULTS_FILE (re-sent with the re-prompt answer)"
else
  warn "results file disappeared — re-send from the phone"
fi

# ── Stage 6: Android (optional) ─────────────────────────────────────────────
stage "Android Chrome (optional)"
if confirm "Do you have an Android to test? (skip if not)"; then
  say "Same three steps as the iPhone, on Android Chrome:"
  step "browser tests:  $SERVER_URL/device-check/  → send with label android-chrome"
  ask ANDROID_LABEL "Android label (default android-chrome):"
  step "camera prototype:  $SERVER_URL/index.html?camera=a  → send with the same label"
  step "camera notes: fill 'Camera prototype notes' on the device-check page"
  pause "When the phone has sent its results, press Enter."
  ANDROID_RESULTS_FILE="$RESULTS_DIR/${ANDROID_LABEL:-android-chrome}.json"
  if [[ -f "$ANDROID_RESULTS_FILE" ]]; then
    say "✓ received $ANDROID_RESULTS_FILE"
  else
    warn "no results file at $ANDROID_RESULTS_FILE"
  fi
else
  note "  skipped — Android facts stay unmeasured for ticket #33"
fi

# ── Stage 7: assemble findings ──────────────────────────────────────────────
stage "Assemble findings"
say "Runs the report script over device-check/results/*.json and writes:"
say "  device-check/findings.md"
step "generating"
if node scripts/device-check-report.mjs; then
  say "✓ wrote device-check/findings.md"
else
  warn "report script failed — check the JSON files by hand"
fi
pause "Ready to stop the server?"

# ── Stage 8: finish ─────────────────────────────────────────────────────────
stage "Stop the server"
if [[ "$SERVER_STARTED_BY_US" == "1" ]]; then
  if [[ -f "$SERVER_PID" ]]; then
    kill "$(cat "$SERVER_PID")" 2>/dev/null && say "✓ stopped the server (pid $(cat "$SERVER_PID"))" || true
    rm -f "$SERVER_PID"
  fi
else
  note "  the server was already running before this wizard — leaving it alone"
fi
note "  findings: device-check/findings.md"
note "  results:  $RESULTS_DIR/"
note "  next: paste the findings into the ticket #33 resolution"

finish
